class A { x: number; s: string; }
class B { y: number[]; }
class C { v: number; w: string; }
function main(): void {
  const a = new A();
  console.log("hi", 1 + 2);
  console.log(a.x === undefined);
  const b = new B();
  b.y = [1];
  console.log(b.y.length);
  const c = new C();
  c.v = 2; c.w = "k";
  console.log(c, c.v + 1);
}
